import json
from messages import sanitize

# Test case 1: Basic sanitization
def test_basic_sanitization():
    messages = [
        {"id": 1, "content": "Hello", "model": "gpt-3", "meta": {"user": "A"}},
        {"content": "World", "model": "gpt-4"}
    ]
    expected = [
        {"content": "Hello"},
        {"content": "World"}
    ]
    assert sanitize(messages) == expected

# Test case 2: Message with all fields to be removed
def test_all_fields_removed():
    messages = [
        {"id": 1, "output": "test", "model": "m", "meta": {}}
    ]
    expected = [
        {}
    ]
    assert sanitize(messages) == expected

# Test case 3: Message with no fields to be removed (only content)
def test_only_content_present():
    messages = [
        {"content": "Just content"}
    ]
    expected = [
        {"content": "Just content"}
    ]
    assert sanitize(messages) == expected

# Test case 4: Empty list
def test_empty_list():
    messages = []
    expected = []
    assert sanitize(messages) == expected

# Test case 5: Mixed fields
def test_mixed_fields():
    messages = [
        {"id": 1, "content": "A", "model": "M1"},
        {"content": "B", "meta": {}}
    ]
    expected = [
        {"content": "A"},
        {"content": "B"}
    ]
    assert sanitize(messages) == expected

print("All tests passed!")
